function reducer(state, action) {
  switch (action.type) {
    case 'inc': return { count: state.count + 1 };
    case 'dec': return { count: state.count - 1 };
    case 'reset': return { count: 0 };
    default: return state;
  }
}

function App() {
  const [state, dispatch] = useReducer(reducer, { count: 0 });
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Count: {state.count}</h2>
      <button onClick={() => dispatch({ type: 'dec' })}>-1</button>
      <button onClick={() => dispatch({ type: 'inc' })} style={{ marginLeft: 8 }}>+1</button>
      <button onClick={() => dispatch({ type: 'reset' })} style={{ marginLeft: 8 }}>reset</button>
    </div>
  );
}

function reducer(todos, action) {
  switch (action.type) {
    case 'add':
      return [...todos, { id: Date.now(), text: action.text, done: false }];
    case 'toggle':
      return todos.map(t => t.id === action.id ? { ...t, done: !t.done } : t);
    case 'remove':
      return todos.filter(t => t.id !== action.id);
    default:
      return todos;
  }
}

function App() {
  const [todos, dispatch] = useReducer(reducer, []);
  const [text, setText] = useState('');
  const add = () => { if (text.trim()) { dispatch({ type: 'add', text }); setText(''); } };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={text} onChange={e => setText(e.target.value)} placeholder="New todo" />
      <button onClick={add} style={{ marginLeft: 8 }}>Add</button>
      <ul>
        {todos.map(t => (
          <li key={t.id}>
            <span onClick={() => dispatch({ type: 'toggle', id: t.id })} style={{ textDecoration: t.done ? 'line-through' : 'none', cursor: 'pointer' }}>{t.text}</span>
            <button onClick={() => dispatch({ type: 'remove', id: t.id })} style={{ marginLeft: 8 }}>x</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

