function reducer(state, action) {
  switch (action.type) {
    case 'increment':
      return { ...state, count: state.count + state.step };
    case 'decrement':
      return { ...state, count: state.count - state.step };
    case 'setStep':
      return { ...state, step: Number(action.step) || 0 };
    default:
      return state;
  }
}

function App() {
  const [state, dispatch] = useReducer(reducer, { count: 0, step: 1 });
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Count: {state.count}</h2>
      <label>Step: <input type="number" value={state.step} onChange={e => dispatch({ type: 'setStep', step: e.target.value })} /></label>
      <div style={{ marginTop: 8 }}>
        <button onClick={() => dispatch({ type: 'decrement' })}>-</button>
        <button onClick={() => dispatch({ type: 'increment' })} style={{ marginLeft: 8 }}>+</button>
      </div>
    </div>
  );
}

