function init(initialCount) {
  return { count: initialCount };
}

function reducer(state, action) {
  switch (action.type) {
    case 'increment': return { count: state.count + 1 };
    case 'decrement': return { count: state.count - 1 };
    case 'reset':     return init(action.payload);
    default:          return state;
  }
}

function App() {
  const initialCount = 10; // imagine this came from a prop
  const [state, dispatch] = useReducer(reducer, initialCount, init);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Count: {state.count}</h2>
      <button onClick={() => dispatch({ type: 'decrement' })}>-1</button>
      <button onClick={() => dispatch({ type: 'increment' })} style={{ marginLeft: 8 }}>+1</button>
      <button onClick={() => dispatch({ type: 'reset', payload: initialCount })} style={{ marginLeft: 8 }}>reset</button>
    </div>
  );
}
